function start(h,intent){assert.ok(intent);const attempt=h.controller.begin(h.lease,intent.form,intent.sections);assert.ok(attempt);return attempt;}
async function execute(h,patch={},sections=['stammdaten']){const intent=capture(h,patch,sections),attempt=start(h,intent),outcome=await h.core.executeClientEditCoreWriteWeb(intent,attempt);return{intent,attempt,outcome};}
