test('Public attachment and child tokens are actually empty frozen opaque objects, view exposes only ten fields and metadata',async()=>{const h=await opened(),view=h.s.viewClientIdentityEditWeb(h.token);assert.deepEqual(Reflect.ownKeys(h.token),[]);assert.deepEqual(Reflect.ownKeys(h.attachment),[]);assert.ok(Object.isFrozen(h.token));assert.equal(Object.hasOwn(view,'original'),false);assert.equal(Object.hasOwn(view,'draft'),false);assert.equal(Object.hasOwn(view,'owner'),false);assert.equal(Object.keys(view.fields).length,10);assert.equal(Object.hasOwn(view.fields,'insuranceNumber'),false);assert.equal(Object.hasOwn(view.fields,'supportWishes'),false);assert.equal(Object.hasOwn(view.fields,'recordNative'),false);assert.equal(view.fields.admissionDate.value,'2000-02-29');assert.equal(view.fields.serviceStart.value,'2011-02-08');assert.equal(h.writes.length,0);});
