test('Current Parent warns before browser unload for its pending/unknown owner even when denied reads hide the child',async t=>{
 const previous=globalThis.window,listeners=new Set();globalThis.window={addEventListener:(name,fn)=>{if(name==='beforeunload')listeners.add(fn);},removeEventListener:(name,fn)=>{if(name==='beforeunload')listeners.delete(fn);}};
 const h=await parentReady(t);t.after(()=>{globalThis.window=previous;});const token=await parentOpened(h),wait=deferred();h.identitySession.updateClientIdentityEditWeb(token,'firstName','Pending');h.state.nativeIntercept=(_table,mode)=>mode==='update'?wait.promise:undefined;const saving=h.identitySession.saveClientIdentityEditWeb(token);await parent.until(h,()=>h.nativeWrites.length===1);h.permissionAPIs[0].refreshPermissions();assert.equal(h.identitySession.viewClientIdentityEditWeb(token),null);let prevented=0;const event={preventDefault:()=>prevented++,returnValue:undefined};for(const listener of listeners)listener(event);assert.equal(prevented,1);assert.equal(event.returnValue,'');wait.resolve({data:null,error:{message:'Unknown'},status:0});await saving;prevented=0;for(const listener of listeners)listener(event);assert.equal(prevented,1);h.unmount();assert.equal(listeners.size,0);assert.equal(h.nativeWrites.length,1);
});
test('Actual Parent outer unmount closes held modal input/save/close and retains the whole original dirty draft privately',async t=>{
 const h=await parentReady(t),token=await parentOpened(h),m=modalRunner(h.identitySession,token);t.after(()=>m.dispose());m.api.handleInput('firstName','Private retained');h.unmount();m.api.handleInput('firstName','No revive');await m.api.handleSave();await m.api.handleClose();assert.equal(h.identitySession.viewClientIdentityEditWeb(token),null);assert.equal(h.nativeWrites.length,0);assert.equal(h.routes.length,0);assert.equal(h.api.identityWorkBlocked(),true);
});

for(const action of ['view','update','close'])test(`Last Session SDK accessor cannot return current ${action} after switching actual runtime mode`,async()=>{
 const seed=await opened();let calls=0,lastBeforeInput=0;seed.state.sessionSdkAccess=()=>{calls++;if([...seed.s.owners.values()][0].generation.draft?.firstName==='Original')lastBeforeInput=calls;};if(action==='view')seed.s.viewClientIdentityEditWeb(seed.token);else if(action==='update')seed.s.updateClientIdentityEditWeb(seed.token,'firstName','Observed');else await seed.s.closeClientIdentityEditWeb(seed.token,async()=>true);assert.ok(calls>0);const boundary=action==='update'?lastBeforeInput:calls;assert.ok(boundary>0);
 const h=await opened();let index=0,atLoss=null;h.state.sessionSdkAccess=()=>{if(++index===boundary){atLoss=[...h.s.owners.values()][0].generation.draft?.firstName;h.state.mode='demo';}};
 if(action==='view')assert.equal(h.s.viewClientIdentityEditWeb(h.token),null);else if(action==='update'){const accepted=h.s.updateClientIdentityEditWeb(h.token,'firstName','Changed');assert.equal(atLoss,'Original');assert.equal([...h.s.owners.values()][0].generation.draft.firstName,'Original');assert.equal(accepted,false);}else{await h.s.closeClientIdentityEditWeb(h.token,async()=>true);assert.equal(h.events.closed,0);}
 assert.equal(h.state.mode,'demo');assert.equal(h.writes.length,0);h.state.mode='supabase';assert.equal(h.s.viewClientIdentityEditWeb(h.token),null);
});
